writeFull("OmniFlow-Control-Plane/portal_sequences.py", "trigger_keyword", true,
"\"\"\"Deterministic multi-step sequences for brand-new contacts.\"\"\"\n\nimport logging\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\nimport portal_db\nimport portal_growth\n\nbp = Blueprint(\"portal_sequences\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nSEQUENCES_TABLE = \"portal_sequences\"\nSTEPS_TABLE = \"portal_sequence_steps\"\nENROLLMENTS_TABLE = \"portal_sequence_enrollments\"\nMAX_STEPS = 5\nMAX_BODY = 1000\nMAX_DELAY_HOURS = 168\n\n_SEQ_DDL_READY = False\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None:\n        return None\n    try:\n        return value.isoformat()\n    except AttributeError:\n        return None\n\n\ndef _normalize_keyword(raw: Any) -> Optional[str]:\n    \"\"\"Lowercase, collapse spaces, cap at 32 chars; None when blank.\"\"\"\n    text = \" \".join(str(raw or \"\").split()).lower()\n    if not text:\n        return None\n    return text[:32]\n\n\ndef _ensure_seq_tables(conn) -> None:\n    global _SEQ_DDL_READY\n    if _SEQ_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(SEQUENCES_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" name TEXT NOT NULL,\"\n            \" enabled BOOLEAN NOT NULL DEFAULT FALSE,\"\n            \" created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n        )\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(STEPS_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" sequence_id BIGINT NOT NULL,\"\n            \" step_no INT NOT NULL,\"\n            \" delay_hours INT NOT NULL DEFAULT 0,\"\n            \" body TEXT NOT NULL)\"\n        )\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" sequence_id BIGINT NOT NULL,\"\n            \" conversation_id BIGINT NOT NULL,\"\n            \" contact_id TEXT NOT NULL,\"\n            \" contact_name TEXT,\"\n            \" current_step INT NOT NULL DEFAULT 0,\"\n            \" next_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" status TEXT NOT NULL DEFAULT 'active',\"\n            \" enrolled_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n            \" CONSTRAINT uq_sequence_enrollment\"\n            \" UNIQUE (sequence_id, conversation_id))\"\n        )\n        cur.execute(\n            \"CREATE INDEX IF NOT EXISTS idx_sequence_enrollments_due\"\n            \" ON \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" (client_id, status, next_at)\"\n        )\n        cur.execute(\n            \"ALTER TABLE \" + portal_db._q(SEQUENCES_TABLE) +\n            \" ADD COLUMN IF NOT EXISTS trigger_keyword TEXT\"\n        )\n    conn.commit()\n    _SEQ_DDL_READY = True\n\n\ndef _parse_steps(raw: Any, client_id: int, sequence_id: int, cur) -> Optional[int]:\n    \"\"\"Validate and persist steps; returns count or None when invalid.\"\"\"\n    if not isinstance(raw, list) or not (1 <= len(raw) <= MAX_STEPS):\n        return None\n    cleaned = []\n    for index, item in enumerate(raw):\n        if not isinstance(item, dict):\n            return None\n        body = str(item.get(\"body\") or \"\").strip()\n        if not body or len(body) > MAX_BODY:\n            return None\n        try:\n            delay = int(item.get(\"delay_hours\", 0))\n        except (TypeError, ValueError):\n            return None\n        if delay < 0 or delay > MAX_DELAY_HOURS:\n            return None\n        if index == 0 and delay < 0:\n            return None\n        cleaned.append((index + 1, delay, body))\n    for step_no, delay, body in cleaned:\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(STEPS_TABLE) +\n            \" (client_id, sequence_id, step_no, delay_hours, body)\"\n            \" VALUES (%s, %s, %s, %s, %s)\",\n            (client_id, sequence_id, step_no, delay, body),\n        )\n    return len(cleaned)\n\n\ndef _steps_public(rows) -> list:\n    return [\n        {\n            \"step_no\": int(row.get(\"step_no\") or 0),\n            \"delay_hours\": int(row.get(\"delay_hours\") or 0),\n            \"body\": row.get(\"body\") or \"\",\n        }\n        for row in rows\n    ]\n\n\ndef _sequence_public(row: Dict[str, Any], steps, active_count: int) -> dict:\n    return {\n        \"id\": row.get(\"id\"),\n        \"name\": row.get(\"name\") or \"\",\n        \"enabled\": row.get(\"enabled\") is True,\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"steps\": steps,\n        \"active_enrollments\": active_count,\n        \"trigger_keyword\": row.get(\"trigger_keyword\") or None,\n    }\n\n\n@bp.get(\"/sequences\")\ndef list_sequences():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, name, enabled, created_at FROM \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" WHERE client_id = %s ORDER BY id DESC LIMIT 20\",\n                    (principal[\"client_id\"],),\n                )\n                sequences = portal_db.rows(cur)\n                result = []\n                for row in sequences:\n                    cur.execute(\n                        \"SELECT step_no, delay_hours, body FROM \" + portal_db._q(STEPS_TABLE) +\n                        \" WHERE client_id = %s AND sequence_id = %s ORDER BY step_no\",\n                        (principal[\"client_id\"], row.get(\"id\")),\n                    )\n                    steps = _steps_public(portal_db.rows(cur))\n                    cur.execute(\n                        \"SELECT COUNT(*) AS total FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n                        \" WHERE client_id = %s AND sequence_id = %s AND status = 'active'\",\n                        (principal[\"client_id\"], row.get(\"id\")),\n                    )\n                    counts = portal_db.rows(cur)\n                    active_count = int(counts[0].get(\"total\") or 0) if counts else 0\n                    result.append(_sequence_public(row, steps, active_count))\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"sequences read failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"sequences read\")[0]), 503\n    return jsonify({\"sequences\": result}), 200\n\n\n@bp.post(\"/sequences\")\ndef create_sequence():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    name = str(payload.get(\"name\") or \"\").strip()[:120]\n    if not name:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"A name is required.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                keyword = _normalize_keyword(payload.get(\"trigger_keyword\"))\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" (client_id, name, enabled, trigger_keyword)\"\n                    \" VALUES (%s, %s, FALSE, %s)\"\n                    \" RETURNING id, name, enabled, created_at, trigger_keyword\",\n                    (principal[\"client_id\"], name, keyword),\n                )\n                rows = portal_db.rows(cur)\n                created = rows[0] if rows else {}\n                sequence_id = int(created.get(\"id\") or 0)\n                count = _parse_steps(payload.get(\"steps\"), principal[\"client_id\"],\n                                     sequence_id, cur)\n                if count is None:\n                    conn.rollback()\n                    return jsonify({\"error\": {\"code\": \"bad_request\",\n                                              \"message\": \"Steps: 1 to 5, each with text and a 0-168h delay.\"}}), 400\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"sequence.created\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Sequence '\" + name + \"' with \" + str(count) + \" steps.\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"sequence create\")[0]), 503\n    return jsonify({\"ok\": True,\n                    \"sequence\": _sequence_public(created, [], 0)}), 200\n\n\n@bp.put(\"/sequences/<int:sequence_id>\")\ndef update_sequence(sequence_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    changes = []\n    params: list = []\n    if \"name\" in payload:\n        name = str(payload.get(\"name\") or \"\").strip()[:120]\n        if not name:\n            return jsonify({\"error\": {\"code\": \"bad_request\",\n                                      \"message\": \"Name cannot be empty.\"}}), 400\n        changes.append(\"name = %s\")\n        params.append(name)\n    if \"trigger_keyword\" in payload:\n        changes.append(\"trigger_keyword = %s\")\n        params.append(_normalize_keyword(payload.get(\"trigger_keyword\")))\n    if \"enabled\" in payload:\n        if not isinstance(payload.get(\"enabled\"), bool):\n            return jsonify({\"error\": {\"code\": \"bad_request\",\n                                      \"message\": \"enabled must be true or false.\"}}), 400\n        changes.append(\"enabled = %s\")\n        params.append(payload.get(\"enabled\"))\n    if not changes:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Nothing to update.\"}}), 400\n    params.extend([sequence_id, principal[\"client_id\"]])\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" SET \" + \", \".join(changes) +\n                    \" WHERE id = %s AND client_id = %s\"\n                    \" RETURNING id\",\n                    tuple(params),\n                )\n                rows = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"sequence update\")[0]), 503\n    if not rows:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Sequence not found.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.delete(\"/sequences/<int:sequence_id>\")\ndef delete_sequence(sequence_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" WHERE client_id = %s AND sequence_id = %s\",\n                    (principal[\"client_id\"], sequence_id),\n                )\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(STEPS_TABLE) +\n                    \" WHERE client_id = %s AND sequence_id = %s\",\n                    (principal[\"client_id\"], sequence_id),\n                )\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (sequence_id, principal[\"client_id\"]),\n                )\n                rows = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"sequence delete\")[0]), 503\n    if not rows:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Sequence not found.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/sequences/<int:sequence_id>/enrollments\")\ndef list_enrollments(sequence_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT 1 FROM \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s\",\n                    (sequence_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Sequence not found.\"}}), 404\n                cur.execute(\n                    \"SELECT id, contact_name, contact_id, current_step, status,\"\n                    \" next_at, enrolled_at FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" WHERE client_id = %s AND sequence_id = %s\"\n                    \" ORDER BY id DESC LIMIT 20\",\n                    (principal[\"client_id\"], sequence_id),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"enrollments read\")[0]), 503\n    return jsonify({\"enrollments\": [\n        {\n            \"id\": row.get(\"id\"),\n            \"contact_name\": row.get(\"contact_name\"),\n            \"contact_id\": row.get(\"contact_id\"),\n            \"current_step\": int(row.get(\"current_step\") or 0),\n            \"status\": row.get(\"status\") or \"active\",\n            \"next_at\": _iso(row.get(\"next_at\")),\n            \"enrolled_at\": _iso(row.get(\"enrolled_at\")),\n        }\n        for row in found\n    ]}), 200\n\n\ndef _normalize_contact(value: Any) -> str:\n    \"\"\"Normalize a pasted phone number or id to the WhatsApp jid form.\"\"\"\n    text = str(value or \"\").strip()\n    for char in (\" \", \"-\", \"(\", \")\"):\n        text = text.replace(char, \"\")\n    if not text:\n        return \"\"\n    if \"@\" not in text:\n        text = text.lstrip(\"+\") + \"@c.us\"\n    return text\n\n\n@bp.post(\"/sequences/<int:sequence_id>/enrollments\")\ndef enroll_contacts(sequence_id: int):\n    \"\"\"Manually enroll pasted contacts into a sequence.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"contacts\")\n    if not isinstance(raw, list):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"contacts must be a list.\"}}), 400\n    seen: list = []\n    for item in raw[:50]:\n        contact = _normalize_contact(item)\n        if contact and contact not in seen:\n            seen.append(contact)\n    if not seen:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"No valid contacts.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT 1 FROM \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s\",\n                    (sequence_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Sequence not found.\"}}), 404\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" (client_id, sequence_id, conversation_id, contact_id,\"\n                    \" contact_name, current_step, next_at)\"\n                    \" SELECT %s, %s, c.id, c.contact_id, c.contact_name, 0,\"\n                    \" NOW() + make_interval(hours => COALESCE(MIN(st.delay_hours), 0))\"\n                    \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n                    \" LEFT JOIN \" + portal_db._q(STEPS_TABLE) +\n                    \" st ON st.sequence_id = %s AND st.step_no = 1\"\n                    \" WHERE c.client_id = %s AND c.contact_id = ANY(%s)\"\n                    \" AND NOT EXISTS (SELECT 1 FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" e WHERE e.sequence_id = %s AND e.conversation_id = c.id)\"\n                    \" GROUP BY c.id, c.contact_id, c.contact_name\"\n                    \" RETURNING contact_id\",\n                    (principal[\"client_id\"], sequence_id, sequence_id,\n                     principal[\"client_id\"], seen, sequence_id),\n                )\n                enrolled_rows = portal_db.rows(cur)\n                enrolled_ids = {row.get(\"contact_id\") for row in enrolled_rows}\n                skipped = [c for c in seen if c not in enrolled_ids]\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"sequence.enrolled_manually\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Enrolled \" + str(len(enrolled_rows)) + \" contact(s) into\"\n                    \" sequence \" + str(sequence_id) + \".\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"sequence enroll\")[0]), 503\n    return jsonify({\"enrolled\": len(enrolled_rows), \"skipped\": skipped}), 200\n\n\n@bp.delete(\"/sequences/<int:sequence_id>/enrollments/<int:enrollment_id>\")\ndef cancel_enrollment(sequence_id: int, enrollment_id: int):\n    \"\"\"Stop an active enrollment.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seq_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT 1 FROM \" + portal_db._q(SEQUENCES_TABLE) +\n                    \" WHERE id = %s AND client_id = %s\",\n                    (sequence_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Sequence not found.\"}}), 404\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" SET status = 'cancelled'\"\n                    \" WHERE id = %s AND sequence_id = %s AND client_id = %s\"\n                    \" AND status = 'active' RETURNING id\",\n                    (enrollment_id, sequence_id, principal[\"client_id\"]),\n                )\n                if not portal_db.rows(cur):\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Enrollment not found or not active.\"}}), 404\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"sequence.enrollment_cancelled\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Cancelled enrollment \" + str(enrollment_id) + \".\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"enrollment cancel\")[0]), 503\n    return jsonify({\"ok\": True}), 200\n\ndef maybe_enroll_new_contact(client_id, conversation_id, contact_id,\n                             contact_name, conn) -> None:\n    \"\"\"Ingest hook: enroll contacts whose conversation has one message.\"\"\"\n    portal_db.ensure_tables()\n    with conn.cursor() as cur:\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" (client_id, sequence_id, conversation_id, contact_id, contact_name,\"\n            \" current_step, next_at)\"\n            \" SELECT %s, s.id, %s, %s, %s, 0,\"\n            \" NOW() + make_interval(hours => COALESCE(MIN(st.delay_hours), 0))\"\n            \" FROM \" + portal_db._q(SEQUENCES_TABLE) + \" s\"\n            \" LEFT JOIN \" + portal_db._q(STEPS_TABLE) +\n            \" st ON st.sequence_id = s.id AND st.step_no = 1\"\n            \" WHERE s.client_id = %s AND s.enabled IS TRUE\"\n            \" AND NOT EXISTS (SELECT 1 FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" e WHERE e.sequence_id = s.id AND e.conversation_id = %s)\"\n            \" AND (SELECT COUNT(*) FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n            \" m WHERE m.conversation_id = %s) <= 1\"\n            \" GROUP BY s.id\"\n            \" RETURNING id\",\n            (client_id, conversation_id, str(contact_id or \"\"),\n             str(contact_name or \"\"), client_id, conversation_id, conversation_id),\n        )\n        enrolled = portal_db.rows(cur)\n        if enrolled:\n            portal_db.log_action(\n                cur,\n                client_id,\n                \"sequence.enrolled\",\n                \"automation\",\n                None,\n                conversation_id,\n                \"Enrolled \" + str(len(enrolled)) + \" sequence(s).\",\n            )\n\n\ndef maybe_enroll_keyword(client_id, conversation_id, contact_id,\n                         contact_name, body, conn) -> None:\n    \"\"\"Ingest hook: enroll a contact when their message matches a trigger.\"\"\"\n    keyword = _normalize_keyword(body)\n    if not keyword:\n        return\n    portal_db.ensure_tables()\n    with conn.cursor() as cur:\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" (client_id, sequence_id, conversation_id, contact_id,\"\n            \" contact_name, current_step, next_at)\"\n            \" SELECT %s, s.id, %s, %s, %s, 0,\"\n            \" NOW() + make_interval(hours => COALESCE(MIN(st.delay_hours), 0))\"\n            \" FROM \" + portal_db._q(SEQUENCES_TABLE) + \" s\"\n            \" LEFT JOIN \" + portal_db._q(STEPS_TABLE) +\n            \" st ON st.sequence_id = s.id AND st.step_no = 1\"\n            \" WHERE s.client_id = %s AND s.enabled IS TRUE\"\n            \" AND s.trigger_keyword = %s\"\n            \" AND NOT EXISTS (SELECT 1 FROM \" + portal_db._q(ENROLLMENTS_TABLE) +\n            \" e WHERE e.sequence_id = s.id AND e.conversation_id = %s)\"\n            \" GROUP BY s.id\"\n            \" RETURNING id\",\n            (client_id, conversation_id, str(contact_id or \"\"),\n             str(contact_name or \"\"), client_id, keyword, conversation_id),\n        )\n        enrolled = portal_db.rows(cur)\n        if enrolled:\n            portal_db.log_action(\n                cur,\n                client_id,\n                \"sequence.enrolled_keyword\",\n                \"automation\",\n                None,\n                conversation_id,\n                \"Keyword '\" + keyword + \"' enrolled \" + str(len(enrolled))\n                + \" sequence(s).\",\n            )\n\n\ndef deliver_due_sequence_steps(cur, client_id: int, conn) -> int:\n    \"\"\"Send due steps for active enrollments (max 5 per poll).\"\"\"\n    try:\n        portal_db.ensure_tables()\n        _ensure_seq_tables(conn)\n    except Exception:\n        return 0\n    try:\n        cur.execute(\n            \"SELECT e.id, e.sequence_id, e.current_step, e.contact_id, e.contact_name\"\n            \" FROM \" + portal_db._q(ENROLLMENTS_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.status = 'active'\"\n            \" AND e.next_at <= NOW()\"\n            \" ORDER BY e.next_at LIMIT 5\",\n            (client_id,),\n        )\n        due = portal_db.rows(cur)\n        sent = 0\n        for row in due:\n            current_step = int(row.get(\"current_step\") or 0)\n            cur.execute(\n                \"SELECT step_no, delay_hours, body FROM \" + portal_db._q(STEPS_TABLE) +\n                \" WHERE client_id = %s AND sequence_id = %s AND step_no > %s\"\n                \" ORDER BY step_no LIMIT 2\",\n                (client_id, row.get(\"sequence_id\"), current_step),\n            )\n            upcoming = portal_db.rows(cur)\n            if not upcoming:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" SET status = 'completed' WHERE id = %s\",\n                    (row.get(\"id\"),),\n                )\n                continue\n            step = upcoming[0]\n            display = str(row.get(\"contact_name\") or \"\").strip()\n            body = str(step.get(\"body\") or \"\").replace(\n                \"{name}\", (display.split(\" \")[0] if display else \"there\")\n            )\n            portal_growth._send_command(\n                cur, client_id, str(row.get(\"contact_id\") or \"\"), display,\n                body, \"sequence\", broadcast_id=None,\n            )\n            finished = len(upcoming) == 1\n            if finished:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" SET current_step = %s, status = 'completed' WHERE id = %s\",\n                    (int(step.get(\"step_no\") or 0), row.get(\"id\")),\n                )\n            else:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(ENROLLMENTS_TABLE) +\n                    \" SET current_step = %s,\"\n                    \" next_at = NOW() + make_interval(hours => %s)\"\n                    \" WHERE id = %s\",\n                    (int(step.get(\"step_no\") or 0),\n                     int(upcoming[1].get(\"delay_hours\") or 0), row.get(\"id\")),\n                )\n            sent += 1\n        if sent:\n            conn.commit()\n        return sent\n    except Exception as error:\n        logger.warning(\"sequence delivery pass failed: %s\", error)\n        return 0\n");


writeFull("Omniflow/app/dashboard/(portal)/sequences/page.tsx", "triggerKeyword", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ninterface Step {\n  step_no: number;\n  delay_hours: number;\n  body: string;\n}\n\ninterface Sequence {\n  id: number;\n  name: string;\n  enabled: boolean;\n  steps: Step[];\n  activeEnrollments: number;\n  triggerKeyword: string | null;\n}\n\ninterface DraftStep {\n  delay_hours: number;\n  body: string;\n}\n\nexport default function SequencesPage() {\n  const [sequences, setSequences] = useState<Sequence[] | null>(null);\n  const [name, setName] = useState(\"\");\n  const [draft, setDraft] = useState<DraftStep[]>([\n    { delay_hours: 0, body: \"\" },\n  ]);\n  const [busy, setBusy] = useState(false);\n  const [note, setNote] = useState(\"\");\n  const [noteTone, setNoteTone] = useState(\"neutral\");\n  const [openLog, setOpenLog] = useState<number | null>(null);\n  const [enrollments, setEnrollments] = useState<\n    { id: number; contact_name: string | null; current_step: number; status: string }[]\n  >([]);\n  const [keyword, setKeyword] = useState(\"\");\n  const [triggerOpenFor, setTriggerOpenFor] = useState<number | null>(null);\n  const [triggerDraft, setTriggerDraft] = useState(\"\");\n  const [triggerBusy, setTriggerBusy] = useState(false);\n  const [addOpenFor, setAddOpenFor] = useState<number | null>(null);\n  const [addDraft, setAddDraft] = useState(\"\");\n  const [addBusy, setAddBusy] = useState(false);\n  const [addNote, setAddNote] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    try {\n      const response = await fetch(\"/api/omniflow/portal/sequences\", {\n        cache: \"no-store\",\n      });\n      const payload: unknown = await response.json().catch(() => null);\n      if (payload !== null && typeof payload === \"object\") {\n        const list = (payload as { sequences?: Sequence[] }).sequences;\n        setSequences(Array.isArray(list) ? list : []);\n      }\n    } catch {\n      setSequences([]);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  const addStep = () => {\n    setDraft((current) =>\n      current.length < 5\n        ? [...current, { delay_hours: 24, body: \"\" }]\n        : current\n    );\n  };\n\n  const patchStep = (index: number, changes: Partial<DraftStep>) => {\n    setDraft((current) =>\n      current.map((step, i) => (i === index ? { ...step, ...changes } : step))\n    );\n  };\n\n  const create = useCallback(async () => {\n    if (!name.trim() || draft.some((step) => !step.body.trim())) {\n      setNoteTone(\"amber\");\n      setNote(\"Give the series a name and fill every step's message.\");\n      return;\n    }\n    setBusy(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\"/api/omniflow/portal/sequences\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(\n          keyword.trim()\n            ? { name, steps: draft, trigger_keyword: keyword.trim() }\n            : { name, steps: draft }\n        ),\n      });\n      if (response.ok) {\n        setNoteTone(\"emerald\");\n        setNote(\n          keyword.trim()\n            ? \"Series created. Send the keyword in a chat to start it.\"\n            : \"Series created. Toggle it on to enroll new contacts.\"\n        );\n        setName(\"\");\n        setKeyword(\"\");\n        setDraft([{ delay_hours: 0, body: \"\" }]);\n        void load();\n        return;\n      }\n      setNoteTone(\"amber\");\n      setNote(\"Could not create. Check steps (1-5, 0-168h each).\");\n    } catch {\n      setNoteTone(\"amber\");\n      setNote(\"Could not create. Try again.\");\n    } finally {\n      setBusy(false);\n    }\n  }, [name, draft, keyword, load]);\n\n  const setEnabled = useCallback(\n    async (row: Sequence, enabled: boolean) => {\n      setBusy(true);\n      try {\n        await fetch(\"/api/omniflow/portal/sequences/\" + String(row.id), {\n          method: \"PUT\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ enabled }),\n        });\n        void load();\n      } catch {\n        void load();\n      } finally {\n        setBusy(false);\n      }\n    },\n    [load]\n  );\n\n  const remove = useCallback(\n    async (row: Sequence) => {\n      setBusy(true);\n      try {\n        await fetch(\"/api/omniflow/portal/sequences/\" + String(row.id), {\n          method: \"DELETE\",\n        });\n        void load();\n      } catch {\n        void load();\n      } finally {\n        setBusy(false);\n      }\n    },\n    [load]\n  );\n\n  const showLog = useCallback(\n    async (id: number) => {\n      if (openLog === id) {\n        setOpenLog(null);\n        return;\n      }\n      setOpenLog(id);\n      setEnrollments([]);\n      try {\n        const response = await fetch(\n          \"/api/omniflow/portal/sequences/\" + String(id) + \"/enrollments\",\n          { cache: \"no-store\" }\n        );\n        const payload: unknown = await response.json().catch(() => null);\n        if (payload !== null && typeof payload === \"object\") {\n          const list = (payload as { enrollments?: typeof enrollments }).enrollments;\n          setEnrollments(Array.isArray(list) ? list : []);\n        }\n      } catch {\n        setEnrollments([]);\n      }\n    },\n    [openLog]\n  );\n\n  const openAdd = useCallback((id: number) => {\n    setAddOpenFor(id);\n    setAddDraft(\"\");\n    setAddNote(null);\n  }, []);\n\n  const openTrigger = useCallback((row: Sequence) => {\n    setTriggerOpenFor(row.id);\n    setTriggerDraft(row.triggerKeyword ?? \"\");\n  }, []);\n\n  const saveTrigger = useCallback(\n    async (row: Sequence) => {\n      if (triggerBusy) return;\n      setTriggerBusy(true);\n      try {\n        await fetch(\"/api/omniflow/portal/sequences/\" + String(row.id), {\n          method: \"PUT\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({\n            triggerKeyword: triggerDraft.trim() ? triggerDraft.trim() : null,\n          }),\n        });\n        setTriggerOpenFor(null);\n        void load();\n      } catch {\n        setTriggerOpenFor(null);\n      } finally {\n        setTriggerBusy(false);\n      }\n    },\n    [triggerBusy, triggerDraft, load]\n  );\n\n  const submitAdd = useCallback(\n    async (id: number) => {\n      const contacts = addDraft\n        .split(/[,;\\n]+/)\n        .map((line) => line.trim())\n        .filter(Boolean);\n      if (addBusy || contacts.length === 0) return;\n      setAddBusy(true);\n      setAddNote(null);\n      try {\n        const response = await fetch(\n          \"/api/omniflow/portal/sequences/\" + String(id) + \"/enrollments\",\n          {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/json\" },\n            body: JSON.stringify({ contacts }),\n          }\n        );\n        const payload = (await response.json().catch(() => null)) as {\n          enrolled?: number;\n          skipped?: string[];\n        } | null;\n        if (response.ok && payload && typeof payload.enrolled === \"number\") {\n          const skipped = Array.isArray(payload.skipped) ? payload.skipped.length : 0;\n          setAddNote(\n            \"Enrolled \" + String(payload.enrolled) +\n              (skipped > 0 ? \" \\u00b7 \" + String(skipped) + \" skipped (no chat yet)\" : \"\")\n          );\n          setAddDraft(\"\");\n          void load();\n        } else {\n          setAddNote(\"Could not add people. Try again.\");\n        }\n      } catch {\n        setAddNote(\"Could not add people. Try again.\");\n      } finally {\n        setAddBusy(false);\n      }\n    },\n    [addBusy, addDraft, load]\n  );\n\n  const cancelEnrollment = useCallback(\n    async (sequenceId: number, enrollmentId: number) => {\n      try {\n        await fetch(\n          \"/api/omniflow/portal/sequences/\" + String(sequenceId) +\n            \"/enrollments/\" + String(enrollmentId),\n          { method: \"DELETE\" }\n        );\n      } catch {\n        // Transient network issue \u2014 reopening the log refreshes it.\n      }\n      void showLog(sequenceId);\n    },\n    [showLog]\n  );\n\n  return (\n    <main className=\"min-h-screen bg-[#07111f] px-4 py-8 sm:px-6\">\n      <div className=\"mx-auto max-w-3xl\">\n        <div className=\"mb-6\">\n          <p className=\"mb-1 text-[10px] font-medium uppercase tracking-[0.2em] text-cyan-400/70\">\n            Workspace\n          </p>\n          <h1 className=\"text-2xl font-semibold tracking-tight text-white\">Sequences</h1>\n          <p className=\"mt-1.5 text-sm text-slate-400\">\n            A multi-message series that new contacts receive automatically,\n            step by step. Great for welcome flows and first-order care.\n          </p>\n        </div>\n\n        <div className=\"mb-6 rounded-2xl border border-white/[0.06] bg-white/[0.015] p-4 sm:p-5\">\n          <h2 className=\"text-sm font-semibold text-white\">New series</h2>\n          <input\n            value={name}\n            onChange={(event) => setName(event.target.value)}\n            placeholder=\"Series name, e.g. Welcome flow\"\n            className=\"mt-3 w-full rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none transition-colors duration-300 focus:border-cyan-400/40\"\n          />\n          <input\n            value={keyword}\n            onChange={(event) => setKeyword(event.target.value)}\n            placeholder=\"Trigger keyword (optional), e.g. CATALOG\"\n            className=\"mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none transition-colors duration-300 focus:border-cyan-400/40\"\n          />\n          <div className=\"mt-3 space-y-2\">\n            {draft.map((step, index) => (\n              <div\n                key={index}\n                className=\"rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\"\n              >\n                <div className=\"flex items-center justify-between gap-2\">\n                  <p className=\"text-[11px] uppercase tracking-wider text-slate-500\">\n                    Step {index + 1}\n                    {index === 0\n                      ? \" \\u00b7 sends after this many hours\"\n                      : \" \\u00b7 waits this many hours\"}\n                  </p>\n                  {draft.length > 1 ? (\n                    <button\n                      type=\"button\"\n                      onClick={() =>\n                        setDraft((current) => current.filter((_, i) => i !== index))\n                      }\n                      className=\"text-[11px] text-slate-500 transition hover:text-rose-300\"\n                    >\n                      Remove\n                    </button>\n                  ) : null}\n                </div>\n                <div className=\"mt-2 flex items-center gap-2\">\n                  <input\n                    type=\"number\"\n                    min={0}\n                    max={168}\n                    value={step.delay_hours}\n                    onChange={(event) =>\n                      patchStep(index, {\n                        delay_hours: Math.max(\n                          0,\n                          Math.min(168, Number(event.target.value) || 0)\n                        ),\n                      })\n                    }\n                    className=\"w-20 shrink-0 rounded-lg border border-white/[0.07] bg-white/[0.02] px-2.5 py-1.5 text-sm text-white outline-none focus:border-cyan-400/40\"\n                  />\n                  <span className=\"shrink-0 text-xs text-slate-500\">hours</span>\n                </div>\n                <textarea\n                  value={step.body}\n                  onChange={(event) => patchStep(index, { body: event.target.value })}\n                  rows={2}\n                  maxLength={1000}\n                  placeholder={\"Use {name} and it becomes each customer's first name.\"}\n                  className=\"mt-2 w-full rounded-lg border border-white/[0.07] bg-white/[0.02] px-3 py-2 text-sm text-white placeholder:text-slate-600 outline-none focus:border-cyan-400/40\"\n                />\n              </div>\n            ))}\n          </div>\n          <div className=\"mt-3 flex flex-wrap items-center gap-3\">\n            {draft.length < 5 ? (\n              <button\n                type=\"button\"\n                onClick={addStep}\n                className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n              >\n                + Add step\n              </button>\n            ) : null}\n            <button\n              type=\"button\"\n              onClick={() => void create()}\n              disabled={busy}\n              className=\"rounded-xl bg-cyan-400/15 px-4 py-2 text-sm font-medium text-cyan-200 transition hover:bg-cyan-400/25 disabled:opacity-50\"\n            >\n              {busy ? \"Working\\u2026\" : \"Create series\"}\n            </button>\n            {note ? (\n              <p\n                className={\n                  \"text-xs \" +\n                  (noteTone === \"emerald\" ? \"text-emerald-300\" : \"text-amber-300\")\n                }\n              >\n                {note}\n              </p>\n            ) : null}\n          </div>\n        </div>\n\n        {sequences === null ? (\n          <p className=\"text-sm text-slate-500\">Loading\\u2026</p>\n        ) : sequences.length === 0 ? (\n          <div className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] px-5 py-8 text-center\">\n            <p className=\"text-sm text-slate-400\">No series yet.</p>\n            <p className=\"mt-1 text-xs text-slate-600\">\n              Create one above; every brand-new contact will walk through it.\n            </p>\n          </div>\n        ) : (\n          <ul className=\"space-y-2\">\n            {sequences.map((row) => (\n              <li\n                key={row.id}\n                className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] p-4\"\n              >\n                <div className=\"flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between\">\n                  <div className=\"min-w-0\">\n                    <span className=\"flex min-w-0 items-center gap-2\">\n                      <p className=\"truncate text-sm font-medium text-slate-200\">{row.name}</p>\n                      {row.triggerKeyword ? (\n                        <span className=\"shrink-0 rounded-md border border-cyan-400/25 bg-cyan-400/[0.08] px-1.5 py-0.5 text-[10px] text-cyan-300\">\n                          {row.triggerKeyword}\n                        </span>\n                      ) : null}\n                    </span>\n                    <p className=\"mt-0.5 text-[11px] text-slate-500\">\n                      {row.steps.length} step{row.steps.length === 1 ? \"\" : \"s\"} \\u00b7{\" \"}\n                      {row.activeEnrollments} active\n                      {row.enabled ? \" \\u00b7 enrolling\" : \"\"}\n                    </p>\n                  </div>\n                  <div className=\"flex shrink-0 items-center gap-2\">\n                    <button\n                      type=\"button\"\n                      onClick={() => void setEnabled(row, !row.enabled)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                    >\n                      {row.enabled ? \"Turn off\" : \"Turn on\"}\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => void showLog(row.id)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                    >\n                      {openLog === row.id ? \"Hide people\" : \"People\"}\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => openAdd(row.id)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                    >\n                      Add people\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => openTrigger(row)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                    >\n                      Trigger\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => void remove(row)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:border-rose-400/40 hover:text-rose-300\"\n                    >\n                      Delete\n                    </button>\n                  </div>\n                </div>\n                {openLog === row.id ? (\n                  <div className=\"mt-3 rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\">\n                    {enrollments.length === 0 ? (\n                      <p className=\"text-xs text-slate-500\">No enrollments yet.</p>\n                    ) : (\n                      <ul className=\"space-y-1.5\">\n                        {enrollments.map((enrollment) => (\n                          <li\n                            key={enrollment.id}\n                            className=\"flex items-center justify-between gap-2 text-xs\"\n                          >\n                            <span className=\"truncate text-slate-300\">\n                              {enrollment.contact_name || \"Customer\"}\n                            </span>\n                            <span\n                              className={\n                                enrollment.status === \"completed\"\n                                  ? \"text-emerald-300\"\n                                  : \"text-amber-300\"\n                              }\n                            >\n                              {enrollment.status === \"completed\"\n                                ? \"completed\"\n                                : \"step \" + String(enrollment.current_step + 1) + \" pending\"}\n                            </span>\n                            {enrollment.status === \"active\" ? (\n                              <button\n                                type=\"button\"\n                                onClick={() => void cancelEnrollment(row.id, enrollment.id)}\n                                className=\"text-[11px] text-slate-500 transition hover:text-rose-300\"\n                              >\n                                Cancel\n                              </button>\n                            ) : null}\n                          </li>\n                        ))}\n                      </ul>\n                    )}\n                  </div>\n                ) : null}\n                {triggerOpenFor === row.id ? (\n                  <div className=\"mt-3 rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\">\n                    <p className=\"text-[11px] uppercase tracking-wider text-slate-500\">\n                      Keyword trigger for {row.name}\n                    </p>\n                    <div className=\"mt-2 flex items-center gap-2\">\n                      <input\n                        value={triggerDraft}\n                        onChange={(event) => setTriggerDraft(event.target.value)}\n                        placeholder=\"e.g. CATALOG\"\n                        className=\"w-44 rounded-lg border border-white/[0.07] bg-white/[0.02] px-2.5 py-1.5 text-sm text-white placeholder:text-slate-600 outline-none focus:border-cyan-400/40\"\n                      />\n                      <button\n                        type=\"button\"\n                        onClick={() => void saveTrigger(row)}\n                        disabled={triggerBusy}\n                        className=\"rounded-lg border border-cyan-400/25 bg-cyan-400/[0.08] px-3 py-1.5 text-xs font-medium text-cyan-200 transition hover:bg-cyan-400/[0.14] disabled:opacity-50\"\n                      >\n                        {triggerBusy ? \"Saving...\" : \"Save\"}\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setTriggerOpenFor(null)}\n                        className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                      >\n                        Close\n                      </button>\n                    </div>\n                    <p className=\"mt-2 text-[10px] text-slate-600\">\n                      When a customer sends exactly this word, the series starts for\n                      them. Leave empty to turn the trigger off.\n                    </p>\n                  </div>\n                ) : null}\n                {addOpenFor === row.id ? (\n                  <div className=\"mt-3 rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\">\n                    <p className=\"text-[11px] uppercase tracking-wider text-slate-500\">\n                      Add people to {row.name}\n                    </p>\n                    <textarea\n                      value={addDraft}\n                      onChange={(event) => setAddDraft(event.target.value)}\n                      rows={3}\n                      placeholder={\"One number per line\\n+92 300 1234567\"}\n                      className=\"mt-2 w-full rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none transition-colors duration-300 focus:border-cyan-400/40\"\n                    />\n                    <div className=\"mt-2 flex items-center gap-2\">\n                      <button\n                        type=\"button\"\n                        onClick={() => void submitAdd(row.id)}\n                        disabled={addBusy || !addDraft.trim()}\n                        className=\"rounded-lg border border-cyan-400/25 bg-cyan-400/[0.08] px-3 py-1.5 text-xs font-medium text-cyan-200 transition hover:bg-cyan-400/[0.14] disabled:opacity-50\"\n                      >\n                        {addBusy ? \"Adding...\" : \"Add to sequence\"}\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setAddOpenFor(null)}\n                        className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                      >\n                        Close\n                      </button>\n                      {addNote ? (\n                        <span className=\"text-[11px] text-slate-400\">{addNote}</span>\n                      ) : null}\n                    </div>\n                    <p className=\"mt-2 text-[10px] text-slate-600\">\n                      Only customers who already have a chat are added. Everyone keeps\n                      their own step position.\n                    </p>\n                  </div>\n                ) : null}\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </main>\n  );\n}\n");


console.log("SUMMARY: " + applied + " applied, " + already + " already done, " + warnings + " warnings");